{"draft":{"version":"a0","html":"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Sticker Table</title>
<style>
  html, body {
    margin: 0;
    padding: 0;
    width: 100%;
    height: 100%;
    overflow: hidden;
    background: #f4ecd8;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
  }
  #wrap {
    position: fixed;
    inset: 0;
    display: flex;
    flex-direction: column;
  }
  canvas {
    display: block;
    touch-action: none;
    flex: 1;
  }
  #bar {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 8px 12px;
    box-sizing: border-box;
    pointer-events: none;
  }
  #counter {
    background: #3d405b;
    color: #f4ecd8;
    font-weight: 700;
    font-size: 18px;
    padding: 8px 16px;
    border-radius: 12px;
    box-shadow: 0 3px 6px rgba(0,0,0,0.25);
    pointer-events: none;
  }
  #clearBtn {
    pointer-events: auto;
    background: #e07a5f;
    color: #f4ecd8;
    border: none;
    font-weight: 700;
    font-size: 16px;
    padding: 10px 20px;
    min-height: 44px;
    border-radius: 14px;
    box-shadow: 0 3px 6px rgba(0,0,0,0.3);
    cursor: pointer;
  }
  #clearBtn:active {
    transform: translateY(1px);
  }
</style>
</head>
<body>
<div id="wrap">
  <canvas id="game"></canvas>
  <div id="bar">
    <div id="counter">Stickers: 0</div>
    <button id="clearBtn">Clear</button>
  </div>
</div>
<script>
const CARTRIDGE = {
  send(type, payload = {}) {
    window.parent.postMessage(
      { source: "cartridge", v: 1, type, payload },
      "*",
    );
  },
};
</script>
<script>
(function() {
  const canvas = document.getElementById("game");
  const ctx = canvas.getContext("2d");
  const clearBtn = document.getElementById("clearBtn");
  const counterEl = document.getElementById("counter");

  let dpr = Math.max(1, window.devicePixelRatio || 1);
  let W = 0, H = 0;

  function resize() {
    W = window.innerWidth;
    H = window.innerHeight;
    dpr = Math.max(1, window.devicePixelRatio || 1);
    canvas.width = Math.round(W * dpr);
    canvas.height = Math.round(H * dpr);
    canvas.style.width = W + "px";
    canvas.style.height = H + "px";
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    draw();
  }
  window.addEventListener("resize", resize);

  // ---- state ----
  const pieces = [];
  let tally = 0;
  let paused = false;
  let running = false;
  let hintPulse = 0;

  const kinds = ["leaf", "shell", "star"];
  let nextKindIndex = 0;

  // simple seeded jitter generator per piece so shapes stay stable
  function mulberry32(seed) {
    return function() {
      seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
      let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  function jitterPoints(points, seed, amount) {
    const rnd = mulberry32(seed);
    return points.map(p => [
      p[0] + (rnd() - 0.5) * amount * 2,
      p[1] + (rnd() - 0.5) * amount * 2
    ]);
  }

  function place(x, y) {
    const kind = kinds[nextKindIndex % kinds.length];
    nextKindIndex++;
    const seed = Math.floor(Math.random() * 1e9);
    const rot = (Math.random() - 0.5) * 0.6;
    const scale = 0.85 + Math.random() * 0.35;
    pieces.push({
      x, y, kind, seed, rot, scale,
      born: performance.now(),
      wobble: 1
    });
    tally += 1;
    counterEl.textContent = "Stickers: " + tally;
    CARTRIDGE.send("score", { value: tally });
  }

  function clearTable() {
    pieces.length = 0;
    tally = 0;
    counterEl.textContent = "Stickers: 0";
    CARTRIDGE.send("score", { value: 0 });
    draw();
  }

  function backToTitle() {
    clearTable();
    running = false;
  }

  clearBtn.addEventListener("click", clearTable);

  // ---- drawing helpers (paper-cut style) ----
  const COLORS = {
    bg: "#f4ecd8",
    layer: "#e07a5f",
    accent: "#3d405b",
    highlight: "#81b29a"
  };

  function roundedPolygon(ctx, pts, radius) {
    // simple polygon path (no rounding complexity needed at this scale)
    ctx.beginPath();
    ctx.moveTo(pts[0][0], pts[0][1]);
    for (let i = 1; i < pts.length; i++) {
      ctx.lineTo(pts[i][0], pts[i][1]);
    }
    ctx.closePath();
  }

  function drawLeaf(ctx, seed, scale) {
    const base = [
      [0, -26], [12, -10], [14, 8], [0, 26], [-14, 8], [-12, -10]
    ].map(p => [p[0]*scale, p[1]*scale]);
    const pts = jitterPoints(base, seed, 1.5);
    ctx.fillStyle = COLORS.highlight;
    ctx.shadowColor = "rgba(61,64,91,0.35)";
    ctx.shadowBlur = 6;
    ctx.shadowOffsetY = 3;
    roundedPolygon(ctx, pts, 4);
    ctx.fill();
    ctx.shadowColor = "transparent";
    ctx.strokeStyle = COLORS.accent;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(0, -22*scale);
    ctx.lineTo(0, 22*scale);
    ctx.stroke();
  }

  function drawShell(ctx, seed, scale) {
    const pts = [];
    const n = 10;
    for (let i = 0; i <= n; i++) {
      const a = Math.PI * (i / n) - Math.PI / 2;
      const r = 22 * scale;
      pts.push([Math.cos(a) * r, Math.sin(a) * r - 4*scale]);
    }
    pts.push([0, 20*scale]);
    const jp = jitterPoints(pts, seed, 1.5);
    ctx.fillStyle = COLORS.layer;
    ctx.shadowColor = "rgba(61,64,91,0.35)";
    ctx.shadowBlur = 6;
    ctx.shadowOffsetY = 3;
    roundedPolygon(ctx, jp, 4);
    ctx.fill();
    ctx.shadowColor = "transparent";
    ctx.strokeStyle = COLORS.accent;
    ctx.lineWidth = 1.2;
    for (let i = 1; i < 5; i++) {
      const a = Math.PI * (i / 5) - Math.PI / 2;
      ctx.beginPath();
      ctx.moveTo(0, 18*scale);
      ctx.lineTo(Math.cos(a) * 20*scale, Math.sin(a) * 20*scale - 4*scale);
      ctx.stroke();
    }
  }

  function drawStar(ctx, seed, scale) {
    const pts = [];
    const spikes = 5;
    const outer = 22 * scale;
    const inner = 9 * scale;
    for (let i = 0; i < spikes * 2; i++) {
      const r = i % 2 === 0 ? outer : inner;
      const a = (Math.PI / spikes) * i - Math.PI / 2;
      pts.push([Math.cos(a) * r, Math.sin(a) * r]);
    }
    const jp = jitterPoints(pts, seed, 1.2);
    ctx.fillStyle = COLORS.accent;
    ctx.shadowColor = "rgba(61,64,91,0.35)";
    ctx.shadowBlur = 6;
    ctx.shadowOffsetY = 3;
    roundedPolygon(ctx, jp, 3);
    ctx.fill();
    ctx.shadowColor = "transparent";
  }

  function drawPiece(p, now) {
    const age = now - p.born;
    const wobbleT = Math.min(age / 500, 1);
    const wobble = Math.sin(wobbleT * Math.PI * 3) * (1 - wobbleT) * 0.15;
    ctx.save();
    ctx.translate(p.x, p.y);
    ctx.rotate(p.rot + wobble);
    const s = p.scale * (0.7 + 0.3 * Math.min(age / 250, 1));
    ctx.scale(s, s);
    if (p.kind === "leaf") drawLeaf(ctx, p.seed, 1);
    else if (p.kind === "shell") drawShell(ctx, p.seed, 1);
    else drawStar(ctx, p.seed, 1);
    ctx.restore();
  }

  function drawBackground() {
    ctx.fillStyle = COLORS.bg;
    ctx.fillRect(0, 0, W, H);
    // subtle table plate - layered rounded rect
    const margin = 14;
    const w = W - margin * 2;
    const h = H - margin * 2;
    ctx.save();
    ctx.shadowColor = "rgba(61,64,91,0.25)";
    ctx.shadowBlur = 8;
    ctx.shadowOffsetY = 4;
    ctx.fillStyle = "#efe3c8";
    roundRect(ctx, margin, margin, w, h, 24);
    ctx.fill();
    ctx.restore();
  }

  function roundRect(ctx, x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }

  function drawHint() {
    if (running) return;
    hintPulse += 0.05;
    const alpha = 0.55 + Math.sin(hintPulse) * 0.35;
    ctx.save();
    ctx.globalAlpha = Math.max(0.15, alpha);
    ctx.fillStyle = COLORS.accent;
    ctx.font = "bold 26px sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("Tap to begin", W / 2, H / 2);
    ctx.restore();
  }

  function draw() {
    drawBackground();
    const now = performance.now();
    for (const p of pieces) drawPiece(p, now);
    drawHint();
  }

  function frame() {
    if (!paused) {
      // no physics settling needed beyond wobble animation via time
    }
    draw();
    requestAnimationFrame(frame);
  }

  // ---- input ----
  canvas.style.touchAction = "none";
  canvas.addEventListener("pointerdown", (event) => {
    event.preventDefault();
    if (paused) return;
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    if (!running) {
      running = true;
      CARTRIDGE.send("start");
      place(x, y);
      return;
    }
    place(x, y);
  });

  // ---- host messages ----
  window.addEventListener("message", (event) => {
    const data = event.data;
    if (!data || data.source !== "cartridge-host") return;
    if (data.type === "pause") paused = true;
    if (data.type === "resume") paused = false;
    if (data.type === "reset") backToTitle();
  });

  // ---- boot ----
  resize();
  CARTRIDGE.send("boot", { title: "Sticker Table", gameType: "toy-box", lang: "en" });
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
"}}

